use serde_json::json;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut total = 0;
    let mut tax_rate = 0;

    for item in input.as_array().unwrap() {
        let (unit_price_cents, quantity) = item.as_array().unwrap()[0].as_array().unwrap()[0].as_i64().unwrap().to_owned();
        let tax_rate_cents = item.as_array().unwrap()[1].as_i64().unwrap().to_owned();

        let unit_price = unit_price_cents as f64 / 100.0;
        let tax = unit_price * tax_rate_cents as f64 / 100.0;
        let total_price = unit_price * quantity as f64 + tax;

        total += total_price as i64;
    }

    json!({ "total": total })
}
